package cn.edu.techgroup.outsourcing.modules.user.event;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;import static org.mockito.Mockito.*;import java.util.Map;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.session.*;
@ExtendWith(MockitoExtension.class)class MemberSessionInvalidationListenerTest{@Mock FindByIndexNameSessionRepository<Session> sessions;MemberSessionInvalidationListener listener;@BeforeEach void setUp(){listener=new MemberSessionInvalidationListener(sessions);}@Test void deletesAllPrincipalSessions(){Session s=mock(Session.class);when(sessions.findByPrincipalName("member")).thenReturn(Map.of("s1",s));listener.handle(new MemberAccessChangedEvent("member"));verify(sessions).deleteById("s1");}@Test void repositoryFailureDoesNotEscape(){when(sessions.findByPrincipalName("member")).thenThrow(new IllegalStateException());assertDoesNotThrow(()->listener.handle(new MemberAccessChangedEvent("member")));}}
